        # find jsonl
        cands=list(Path(root).glob(f"**/{tid}*.jsonl"))
        if not cands:
            cands=list(Path(root, tid).glob("*.jsonl")) if Path(root, tid).exists() else []
        if not cands:
            print(f"{tid}: MISSING"); continue
        p=cands[0]
        users=[]; assistants=[]
        with open(p, errors='replace') as f:
            for line in f:
                try: o=json.loads(line)
                except: continue
                role=o.get("role") or o.get("type") or ""
                # cursor format varies
                content=o.get("content") or o.get("message") or o.get("text") or ""
                if isinstance(content, list):
                    parts=[]
                    for c in content:
                        if isinstance(c, dict):
                            parts.append(str(c.get("text") or c.get("content") or "")[:500])
                        else:
                            parts.append(str(c)[:500])
                    content=" ".join(parts)
                content=str(content).replace("\n"," ")[:400]
                if role in ("user","human") or o.get("type")=="user":
                    if content.strip(): users.append(content[:350])
                if role in ("assistant","ai") or o.get("type")=="assistant":
                    if content.strip(): assistants.append(content[:350])
                # alternate schema: message.role
                msg=o.get("message")
                if isinstance(msg, dict):
                    r=msg.get("role"); c=msg.get("content")
                    if isinstance(c, list):
                        c=" ".join(str(x.get("text","") if isinstance(x,dict) else x) for x in c)
                    c=str(c or "").replace("\n"," ")[:350]
                    if r=="user" and c.strip(): users.append(c)
                    if r=="assistant" and c.strip(): assistants.append(c)
        print(f"\n--- {tid} ({p.stat().st_size}B) users={len(users)} asst={len(assistants)} ---")
        for u in users[:3]:
            print(f"U: {u[:280]}")
        for a in assistants[-2:]:
            print(f"A: {a[:280]}")
